import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_positions"].copy()
    events = inputs["position_events"].copy()

    # 1. Distinct by batch_seq (same event delivered more than once -> apply once)
    events = events.drop_duplicates(subset=["batch_seq"], keep="first")

    # Build target lookup per key
    target_map = {}
    for _, row in target.iterrows():
        key = (row["account_id"], row["symbol"])
        target_map[key] = {
            "qty": row["qty"],
            "price": row["price"],
            "row_version": row["row_version"],
        }

    # 2. Replay guard
    def guard(row):
        key = (row["account_id"], row["symbol"])
        if key in target_map:
            return row["row_version"] > target_map[key]["row_version"]
        return True

    if len(events):
        mask = events.apply(guard, axis=1)
        events = events[mask]

    # 3. Order by row_version, batch_seq within each key
    events = events.sort_values(by=["account_id", "symbol", "row_version", "batch_seq"])

    # state: current row per key (dict with qty/price/row_version) or None if removed/absent
    state = dict(target_map)
    last_effect = {}  # key -> (removed_bool, row_version), only for keys with >=1 effective event

    if len(events):
        for (acct, sym), group in events.groupby(["account_id", "symbol"], sort=False):
            key = (acct, sym)
            current = state.get(key)
            last_removed = None
            last_version = None
            has_effect = False

            for _, ev in group.iterrows():
                op = ev["op"]
                qty = ev["qty"]
                price = ev["price"]
                version = ev["row_version"]

                effect = False
                removed = False

                if op == "D":
                    if current is not None:
                        current = None
                        effect = True
                        removed = True
                    # else: no-op, nothing changes
                elif op in ("I", "U"):
                    qty_val = qty
                    is_zero = (not pd.isna(qty_val)) and (qty_val == 0)

                    if is_zero:
                        if current is not None:
                            current = None
                            effect = True
                            removed = True
                        # else: no-op
                    else:
                        if current is not None:
                            if op == "U" and pd.isna(price):
                                new_price = current["price"]
                            else:
                                new_price = None if pd.isna(price) else price
                            current = {
                                "qty": qty_val,
                                "price": new_price,
                                "row_version": version,
                            }
                        else:
                            new_price = None if pd.isna(price) else price
                            current = {
                                "qty": qty_val,
                                "price": new_price,
                                "row_version": version,
                            }
                        effect = True
                        removed = False
                else:
                    # unknown op: treat as no-op
                    effect = False

                if effect:
                    last_removed = removed
                    last_version = version
                    has_effect = True

            state[key] = current
            if has_effect:
                last_effect[key] = (last_removed, last_version)

    # Build new_positions
    rows = []
    for key, val in state.items():
        if val is not None:
            rows.append(
                {
                    "account_id": key[0],
                    "symbol": key[1],
                    "qty": val["qty"],
                    "price": val["price"],
                    "row_version": val["row_version"],
                }
            )

    new_positions = pd.DataFrame(
        rows, columns=["account_id", "symbol", "qty", "price", "row_version"]
    )

    if len(new_positions):
        new_positions["account_id"] = new_positions["account_id"].astype("int64")
        new_positions["qty"] = new_positions["qty"].astype("int64")
        new_positions["row_version"] = new_positions["row_version"].astype("int64")
        new_positions["price"] = new_positions["price"].astype("float64")
    else:
        new_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "qty": pd.Series(dtype="int64"),
                "price": pd.Series(dtype="float64"),
                "row_version": pd.Series(dtype="int64"),
            }
        )

    # Build closed_positions
    closed_rows = []
    for key, (removed, version) in last_effect.items():
        if removed:
            closed_rows.append(
                {
                    "account_id": key[0],
                    "symbol": key[1],
                    "closed_version": version,
                }
            )

    closed_positions = pd.DataFrame(
        closed_rows, columns=["account_id", "symbol", "closed_version"]
    )

    if len(closed_positions):
        closed_positions["account_id"] = closed_positions["account_id"].astype("int64")
        closed_positions["closed_version"] = closed_positions["closed_version"].astype(
            "int64"
        )
    else:
        closed_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "closed_version": pd.Series(dtype="int64"),
            }
        )

    return {"new_positions": new_positions, "closed_positions": closed_positions}
